import { MeshBasicNodeMaterial } from 'three/webgpu';
import { vec3, smoothstep, uv, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, DoubleSide, SRGBColorSpace } = ctx.THREE;

  const group = new Group();
  group.name = 'hub-collection-card-3-label';

  const colors = config.intent?.visualSpec?.colors ?? {};
  const inkHex = colors.ink ?? '#16161d';
  const paperHex = colors.paper ?? '#e8ecf2';
  const accentHex = colors.accent ?? '#ff2a38';
  const surfaceHex = colors.surface ?? '#0b0b10';

  const ink = new Color(inkHex);
  const paper = new Color(paperHex);
  const accent = new Color(accentHex);
  const surface = new Color(surfaceHex);

  // inner group is what we animate; adapter positions the outer group
  const inner = new Group();
  group.add(inner);

  const cardW = 1.28;
  const cardH = 0.8;

  // ---- Card surface (textured plane) ----
  const cardGeo = new PlaneGeometry(cardW, cardH);
  const cardMat = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide });

  let loadedTex = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = SRGBColorSpace;
      cardMat.map = tex;
      cardMat.needsUpdate = true;
      loadedTex = tex;
    });
  }
  const card = new Mesh(cardGeo, cardMat);
  card.position.set(0, 0, 0);
  inner.add(card);

  // ---- Engineered gradient overlay (darken bottom for text legibility) ----
  const overlayGeo = new PlaneGeometry(cardW, cardH);
  const overlayMat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    depthWrite: false,
  });
  overlayMat.colorNode = vec3(surface.r, surface.g, surface.b);
  overlayMat.alphaNode = smoothstep(float(0.62), float(0.0), uv().y);
  const overlay = new Mesh(overlayGeo, overlayMat);
  overlay.position.set(0, 0, 0.001);
  inner.add(overlay);

  // ---- Accent line (signal red, < 10% of frame) ----
  const accentGeo = new PlaneGeometry(cardW * 0.14, 0.014);
  const accentMat = new MeshBasicNodeMaterial({ color: accent, transparent: true });
  const accentLine = new Mesh(accentGeo, accentMat);
  accentLine.position.set(-cardW / 2 + 0.12, cardH / 2 - 0.14, 0.002);
  inner.add(accentLine);

  // ---- Text content via fontAtlas ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textMeshes = [];
  for (const item of items) {
    if (!item || item.text == null) continue;
    const px = item.typography?.fontSize ?? 39;
    const fontSize = (px / 512) * cardW; // atlas-region-relative scale
    const t = ctx.fontAtlas.createText(String(item.text), {
      fontSize,
      color: paperHex,
      align: 'left',
      letterSpacingPx: 0.5,
    });
    t.position.set(-cardW / 2 + 0.12, -cardH / 2 + 0.13, 0.003);
    inner.add(t);
    textMeshes.push(t);
  }

  // ---- Entrance: weighted-settle rise-in ----
  const tl = gsap.timeline();
  tl.from(inner.position, { y: 0.25, duration: 0.7, ease: 'power3.out', delay: 0.2 })
    .from(inner.scale, { x: 0.95, y: 0.95, duration: 0.9, ease: 'power4.out' }, 0)
    .to(inner.scale, { x: 1.04, duration: 0.45, ease: 'power2.out' }, 0.7)
    .to(inner.scale, { x: 1.0, y: 1.0, duration: 0.45, ease: 'power4.out' }, 1.05);

  // ---- Handlers (static node: no interactivity) ----
  group.userData.handlers = {};

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    tl.kill();
    cardGeo.dispose();
    cardMat.dispose();
    overlayGeo.dispose();
    overlayMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    if (loadedTex) loadedTex.dispose();
    textMeshes.forEach((m) => {
      m.traverse?.((o) => {
        if (o.geometry) o.geometry.dispose();
        if (o.material) {
          if (Array.isArray(o.material)) o.material.forEach((mm) => mm.dispose());
          else o.material.dispose();
        }
      });
    });
  };

  return group;
}
